 const messages=[{body:"Hey Dejon, I saw your ad about buying houses for cash. I have a property at 4521 Lenox Ave that I am considering selling. Are you still buying?",time:'9:12 AM',outgoing:false},{body:'Yes, absolutely! We buy houses as-is, in any condition. I can take a look and discuss an offer. When would be a good time to see the property?',time:'9:14 AM',outgoing:true},{body:'That sounds good. I am available tomorrow morning. The house needs some work, but I am ready to sell.',time:'9:16 AM',outgoing:false}];
