 function saveDraft(){if(isEditing.value||!draft.value.trim())return;drafts.value.push(draft.value.trim());draft.value='';feedback.value='Draft kept for this session · not sent.';}
 async function openDetail(title,lines){if(isEditing.value)return;previousFocus=wwLib.getFrontDocument().activeElement;detail.value={title,lines};await nextTick();closeButton.value?.focus();}
 function closeDetail(){detail.value=null;previousFocus?.focus();}
 return{metrics,sequences,emails,selectedMail,filtered,search,tab,messages,campaigns,tasks,draft,drafts,feedback,detail,closeButton,chooseMail,saveDraft,openDetail,closeDetail};
